(()=>{const el=id=>document.getElementById(id),n=id=>Number(el(id).value)||0,f=v=>new Intl.NumberFormat('en-IE',{maximumFractionDigits:1}).format(v);function update(){const h=n('prep-hours')*n('calc-labs')*n('calc-weeks-year'),r=(n('prep-rate')/Number(document.getElementById('prep-paid-hours').value)),free=h*n('prep-reduction')/100;['hours','rate','reduction'].forEach((key,i)=>el('prep-'+key+'-readout').textContent=f(n('prep-'+key))+' '+['h/week','€/year','%'][i]);for(const [k,x,unit] of [['base',h,' h'],['cost',h*r,''],['free',free,' h'],['value',free*r,'']])for(const [period,m] of [['year',1],['three',3]])el('prep-'+k+'-'+period).textContent=!n('prep-hours')?'Enter preparation hours':(!unit&&!r?'Enter annual salary':(unit?'':'€')+f(x*m)+unit);}['prep-hours','prep-rate','prep-reduction'].forEach(id=>el(id).addEventListener('input',update));document.addEventListener('resolve-model',update);el('calc-reset').addEventListener('click',()=>{el('prep-hours').value=20;el('prep-rate').value=30000;el('prep-paid-hours').value=2080;el('prep-reduction').value=30;update();});update();})();